def _deepcopy_with_paths(item: _T, paths: Sequence[Sequence[str]], memo: dict[int, object]) -> _T:
    if not paths:
        return item

    item_id = id(item)
    if item_id in memo:
        return cast(_T, memo[item_id])

    has_terminal = any(len(p) == 0 for p in paths)
    active_paths = [p for p in paths if len(p) > 0]

    if is_mapping(item) or is_mapping_t(item):
        key_to_paths: dict[str, list[Sequence[str]]] = {}
        for path in active_paths:
            key_to_paths.setdefault(str(path[0]), []).append(path[1:])

        matching_keys = {k: sp for k, sp in key_to_paths.items() if k in item}
        if not matching_keys and not has_terminal:
            return item

        try:
            result = type(item)(item)
        except Exception:
            result = dict(item)

        memo[item_id] = result

        for key, subpaths in matching_keys.items():
            result[key] = _deepcopy_with_paths(result[key], subpaths, memo)
        return cast(_T, result)

    if is_list(item) or is_tuple_t(item) or is_sequence_t(item):
        wildcard_paths = [p[1:] for p in active_paths if p[0] == ARRAY_PATH_SENTINEL]
        idx_paths: dict[int, list[Sequence[str]]] = {}
        for p in active_paths:
            if p[0] != ARRAY_PATH_SENTINEL and isinstance(p[0], (int, str)) and str(p[0]).isdigit():
                idx = int(p[0])
                if 0 <= idx < len(item):
                    idx_paths.setdefault(idx, []).append(p[1:])

        if not wildcard_paths and not idx_paths and not has_terminal:
            return item

        entries: list[object] = []
        for i, entry in enumerate(item):
            subpaths: list[Sequence[str]] = list(wildcard_paths)
            if i in idx_paths:
                subpaths.extend(idx_paths[i])
            if subpaths:
                entries.append(_deepcopy_with_paths(entry, subpaths, memo))
            else:
                entries.append(entry)

        try:
            result = type(item)(entries)
        except Exception:
            result = list(entries) if is_list(item) else tuple(entries)

        memo[item_id] = result
        return cast(_T, result)

    if isinstance(item, (set, frozenset)):
        if not has_terminal and not active_paths:
            return item

        try:
            result = type(item)(item)
        except Exception:
            result = set(item) if isinstance(item, set) else frozenset(item)

